import{_ as p,o,c as a,a5 as n}from"./chunks/framework.Cooo9kuv.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"VBA007-批量修改指定文件夹及其子文件夹下的所有文件名","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["EXCEL批处理"],"标签":["vba代码","vba修改文件名","vba脚本","批量修改文件名"]},"headers":[],"relativePath":"md/EXCEL批处理/VBA007-批量修改指定文件夹及其子文件夹下的所有文件名.md","filePath":"md/EXCEL批处理/VBA007-批量修改指定文件夹及其子文件夹下的所有文件名.md"}'),_={name:"md/EXCEL批处理/VBA007-批量修改指定文件夹及其子文件夹下的所有文件名.md"};function s(e,t,r,c,g,m){return o(),a("div",null,[...t[0]||(t[0]=[n('<p>批量修改指定文件夹下所有文件名，支持子文件夹穿透</p><p>比如A文件夹下有很多文件夹及文件，每个子文件夹下都有文件，那么点击获取文件名后，选择A文件夹路径，会将所有文件包括子文件夹下的文件名列出到A列，然后可以在B列一个文件名一个文件名的修改，也可以在B列统一修改，修改后点击修改文件名按钮就会全部修改。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250223164115174030007537068.png" alt=""></p><p>统一文件名可以使用下方方式实现快速修改输入B1单元格内容后，点击单元格右下角双击如图所示部分，就会自动填充</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250223164251174030017172734.png" alt=""></p><p>还可以使用公式进行填充，</p><p>添加前缀   =&quot;1-&quot;&amp;A2</p><p>添加后缀  =A2&amp;&quot;-1&quot;</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250223164706174030042671651.png" alt=""></p><p>同样是点击B2单元格，然后双击单元格右下角的点，自动填充</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250223164812174030049291271.png" alt=""></p><p>最后点击修改文件名即可实现，全部文件名重命名。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1439.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1439.html</a></p>',14)])])}const d=p(_,[["render",s]]);export{w as __pageData,d as default};
